def transform(g):
    H,W=len(g),len(g[0])
    nz=lambda i,j: 0<=i<H and 0<=j<W and g[i][j]!=0
    # connected regions of nonzero cells
    from collections import deque
    reg=[[-1]*W for _ in range(H)]; n=0; seed={}
    for i in range(H):
        for j in range(W):
            if g[i][j]!=0 and reg[i][j]==-1:
                q=deque([(i,j)]); reg[i][j]=n
                while q:
                    y,x=q.popleft()
                    if g[y][x]!=1: seed.setdefault(n,g[y][x])
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        a,b=y+dy,x+dx
                        if 0<=a<H and 0<=b<W and g[a][b]!=0 and reg[a][b]==-1:
                            reg[a][b]=n; q.append((a,b))
                n+=1
    out=[row[:] for row in g]
    for i in range(1,H-1):
        for j in range(1,W-1):
            if g[i][j]==1 and all(nz(i+di,j+dj) for di in(-1,0,1) for dj in(-1,0,1)):
                out[i][j]=seed.get(reg[i][j],1)
    return out
